def solve(g, bg, seed, wall):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    # BFS with moves right and up, blocked by wall cells
    from collections import deque
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in range(w):
            if g[i][j]==seed: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in ((0,1),(-1,0)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and g[ni][nj]!=wall:
                seen[ni][nj]=True; q.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if g[i][j]==seed: out[i][j]=4
            elif seen[i][j] and g[i][j]==bg: out[i][j]=seed
    return out
